  A.blanks("b2-q12", "Easy", "A* on Romania: g(Arad) = 0 and h(Arad) = 366. f(Arad) = ___ + ___ = ___.", ["g", "h", "f"], ["0", "366", "366"], null, "At the start g = 0.", C(12, a));
  A.blanks("b2-q13", "Medium", "A* from Arad: Sibiu g = 140, h = 253; Timisoara g = 118, h = 329; Zerind g = 75, h = 374. A* expands ___ next because its f-value is ___.", ["node", "f"], ["Sibiu", "393"], [["Sibiu"], ["393"]], "Compare g + h, not g or h alone.", C(13, a, { steps: ["Sibiu 140 + 253 = 393", "Timisoara 118 + 329 = 447", "Zerind 75 + 374 = 449", "Smallest: Sibiu 393."] }));
  A.blanks("b2-q14", "Medium", "A* via Sibiu: Rimnicu Vilcea g = 220, h = 193; Fagaras g = 239, h = 176. A* chooses ___ because 220 + 193 = ___.", ["node", "f"], ["Rimnicu Vilcea", "413"], [["Rimnicu Vilcea", "Rimnicu", "Râmnicu Vâlcea", "Rimnicu Vâlcea"], ["413"]], "Fagaras has 239 + 176 = 415, so Rimnicu Vilcea (413) wins.", C(14, a));
