  A.match("b2-q41", "Easy", "Delivery-route optimisation (Lecture 3). Match each part of the formulation.", [["STATE", "a route (ordering of the stops)"], ["NEIGHBOUR", "swap two stops"], ["OBJECTIVE", "minimise distance"], ["CONSTRAINT", "visit each location once and return to base"]], ["maximise the number of customers"], "State, neighbour, objective, constraint.", P(41, p));
