  A.blanks("b2-q163", "Easy", "Option X: 50% win $100, 50% lose $20. Option Y: 90% win $40, 10% win $0. EU(X) = ___; EU(Y) = ___; choose ___.", ["EU(X)", "EU(Y)", "choice"], ["40", "36", "X"], null, "Weight by probability.", C(163, "mdp-meu", { steps: ["0.5(100) + 0.5(−20) = 40", "0.9(40) = 36"] }));
  A.tf("b2-q164", "Easy", "MEU chooses the action with the best possible outcome.", false, "It chooses the highest expected (probability-weighted) utility.", "Expected, not best-case.", P(164, "mdp-meu"));
  A.blank("b2-q165", "Medium", "Rewards 1, 1, 1, 10 in successive steps, γ = 0.9. G = ___ (1 d.p.).", "10.0", ["10"], "1 + 0.9 + 0.81 + 0.729(10).", C(165, "mdp-utility", { steps: ["1 + 0.9 + 0.81 = 2.71", "0.729 × 10 = 7.29", "Total 10.0"] }));
  A.blank("b2-q166", "Easy", "Reward 2 every step forever, γ = 0.8. G = ___.", "10", [], "r/(1 − γ).", C(166, "mdp-utility"));
  A.blank("b2-q167", "Easy", "With γ = 0 the agent cares only about the ___ reward.", "immediate", ["next", "the immediate", "current", "immediate (next)"], "Short-sighted.", P(167, "mdp-utility"));
  A.mcq("b2-q168", "Easy", "In the 4×3 grid world the living reward is −0.04. Its purpose is to:", "make the agent prefer shorter paths to the +1 exit", [["make the agent avoid the goal", "It pushes toward the goal."], ["represent the wall", "The wall is a blocked square."], ["make the problem deterministic", "Transitions stay stochastic."]], "Each step costs a little.", P(168, "mdp-grid"));
  A.blank("b2-q169", "Hard", "4×3 grid world, converged utilities (γ = 1, R = −0.04): U(4,3) = 1, U(3,3) = 0.918, U(3,2) = 0.660. Q((3,3), Right) = −0.04 + 0.8U(4,3) + 0.1U(3,3) + 0.1U(3,2) = ___ (3 d.p.).", "0.918", ["0.917"], "Equals U(3,3), as Bellman requires.", C(169, "mdp-bellman", { tol: 0.0015, steps: ["Up-slip hits the wall: stay at (3,3).", "−0.04 + 0.8 + 0.0918 + 0.066 = 0.918"] }));
  A.blanks("b2-q170", "Hard", "4×3 grid world (γ = 1, R = −0.04), utilities U(1,1) = 0.705, U(1,2) = 0.762, U(2,1) = 0.655. At (1,1): Q(Up) = ___; Q(Right) = ___ (3 d.p.). Best action ___.", ["Q(Up)", "Q(Right)", "best"], ["0.706", "0.631", "Up"], [["0.706", "0.705"], ["0.631"], ["Up"]], "List landing squares with 0.8/0.1/0.1; bumps mean stay.", C(170, "mdp-bellman", { steps: ["Up: −0.04 + 0.8(0.762) + 0.1(0.705) + 0.1(0.655) = 0.706", "Right: −0.04 + 0.8(0.655) + 0.1(0.762) + 0.1(0.705) = 0.631", "Up wins."] }));
  A.blank("b2-q171", "Medium", "4×3 grid world, value iteration from U0 = 0 everywhere (terminals fixed at +1, −1), γ = 1, R = −0.04. After one update, U1(3,3) = ___.", "0.76", [], "Best is Right: 0.8(1).", C(171, "mdp-vi-pi", { steps: ["Right: −0.04 + 0.8(1) + 0.1(0) + 0.1(0) = 0.76"] }));
  A.blank("b2-q172", "Medium", "Same first value-iteration update at (3,3) but with γ = 0.9: U1(3,3) = ___.", "0.68", [], "−0.04 + 0.9(0.8).", C(172, "mdp-vi-pi"));
  A.tf("b2-q173", "Medium", "In value iteration the Bellman equations are linear.", false, "The max makes them non-linear; with a fixed policy (policy evaluation) they are linear.", "max → non-linear.", P(173, "mdp-vi-pi"));
