  A.mcq("b2-q177", "Easy", "U(s) = max_a ___.", "Q(s, a)", [["π(s)", "π is an action, not a value."], ["R(s)", "Only the immediate reward."], ["P(s′|s, a)", "A probability."]], "Value of state = value of its best action.", P(177, "mdp-bellman"));
