  A.blanks("b2-q183", "Medium", "TD: U(s) = 0.5, U(s′) = 0.8, R = −0.04, γ = 1, α = 0.1. TD target = ___; TD error = ___; new U(s) = ___.", ["target", "error", "new U(s)"], ["0.76", "0.26", "0.526"], null, "U ← U + α(target − U).", C(183, "mdp-td"));
  A.blank("b2-q184", "Easy", "ADP: from state s with action a the agent went to s1 30 times and s2 10 times. P̂(s1 | s, a) = ___.", "0.75", [], "30/40.", C(184, "mdp-passive"));
  A.match("b2-q185", "Medium", "Match the passive RL method.", [["direct utility estimation", "averages observed reward-to-go per state"], ["ADP", "learns a transition model then solves the Bellman equations"], ["TD", "adjusts a state toward its observed successor without a model"]], [], "Three passive methods.", P(185, ["mdp-passive", "mdp-td"]));
  A.tf("b2-q186", "Medium", "TD converges to the same values as ADP as the number of training sequences tends to infinity.", true, "TD is a crude but efficient approximation to ADP.", "Same limit.", P(186, "mdp-td", { trap: false }));
  A.mcq("b2-q187", "Medium", "Which passive method learns nothing until the end of a trial?", "direct utility estimation", [["ADP", "Updates its model each step."], ["TD", "Updates every transition."], ["Q-learning", "Active and per-step."]], "Needs the full reward-to-go.", P(187, "mdp-passive"));
  A.blank("b2-q188", "Medium", "Q-learning: Q(s, a) = 2, R = 1, γ = 0.9, max_a′ Q(s′, a′) = 5, α = 0.5. New Q(s, a) = ___.", "3.75", [], "Q + α[R + γ max Q′ − Q].", C(188, "mdp-qlearning", { steps: ["target 1 + 4.5 = 5.5", "error 3.5", "2 + 0.5(3.5) = 3.75"] }));
  A.blank("b2-q189", "Medium", "Q-learning: Q(s, a) = 0, R = −1, γ = 1, Q(s′, ·) = {2, −3}, α = 0.2. New Q(s, a) = ___.", "0.2", [], "Use the MAX of Q(s′, ·) = 2.", C(189, "mdp-qlearning", { trap: true, steps: ["target −1 + 2 = 1", "0 + 0.2(1 − 0) = 0.2"] }));
  A.tf("b2-q190", "Easy", "Q-learning needs the transition model P(s′|s, a).", false, "It is model-free.", "Model-free.", P(190, "mdp-qlearning"));
  A.blanks("b2-q191", "Easy", "Trying new actions to learn their effects is ___; using known good actions is ___.", ["new actions", "known actions"], ["exploration", "exploitation"], null, "Balance both.", P(191, "mdp-rl"));
